schema:
CREATE TABLE actor (
  actor_id,
  first_name,
  last_name,
  last_update
);

CREATE TABLE category (
  category_id,
  last_update,
  name
);

CREATE TABLE city (
  city,
  city_id,
  country_id,
  last_update
);

CREATE TABLE country (
  country,
  country_id,
  last_update
);

CREATE TABLE film_actor (
  actor_id,
  film_id,
  last_update
);

CREATE TABLE film_category (
  category_id,
  film_id,
  last_update
);

CREATE TABLE film_text (
  description,
  film_id,
  title
);

CREATE TABLE inventory (
  film_id,
  inventory_id,
  last_update,
  store_id
);

CREATE TABLE language (
  language_id,
  last_update,
  name
);

CREATE TABLE store (
  address_id,
  last_update,
  manager_staff_id,
  store_id
);
